using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using ScholarshipExam.Api;
using ScholarshipExam.Core;
using ScholarshipExam.Infrastructure;
using Xunit;

public class TestHost:WebApplicationFactory<Program>{
 public readonly string DbPath=Path.Combine(Path.GetTempPath(),"scholarship-test-"+Guid.NewGuid()+".db");
 protected override void ConfigureWebHost(IWebHostBuilder b){b.UseEnvironment("Testing");b.UseSetting("Database:Provider","Sqlite");b.ConfigureTestServices(s=>{s.RemoveAll<DbContextOptions<AppDb>>();s.RemoveAll<AppDb>();s.AddDbContext<AppDb>(o=>o.UseSqlite("Data Source="+DbPath));});}
}
public class ApiTests:IAsyncLifetime {
 private readonly TestHost host=new(); private HttpClient client=null!; private HttpClient admin=null!;
 private const string Password="Testing-Only-782!";
 public async Task InitializeAsync(){client=host.CreateClient();using var scope=host.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();await db.Database.EnsureCreatedAsync();var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Bootstrap:Email","admin@example.test"},{"Bootstrap:Password",Password}}).Build();await Seeder.Run(scope.ServiceProvider,config);admin=await Login("admin@example.test");}
 public async Task DisposeAsync(){client.Dispose();admin.Dispose();await host.DisposeAsync();try{File.Delete(host.DbPath);}catch(IOException){}}
 private async Task<HttpClient> Login(string email){var c=host.CreateClient();var response=await c.PostAsJsonAsync("/api/auth/login",new{email,password=Password});Assert.True(response.IsSuccessStatusCode,await response.Content.ReadAsStringAsync());var token=(await response.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("accessToken").GetString();c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token);return c;}
 private async Task<HttpClient> Student(){var email=Guid.NewGuid()+"@example.test";var r=await client.PostAsJsonAsync("/api/auth/register",new{email,password=Password,displayName="Test Student",role="Student",guardianConsent=true});Assert.Equal(HttpStatusCode.Created,r.StatusCode);return await Login(email);}
 private static async Task<JsonElement> Read(HttpResponseMessage r){Assert.True(r.IsSuccessStatusCode,await r.Content.ReadAsStringAsync());return await r.Content.ReadFromJsonAsync<JsonElement>();}
 private async Task<List<Guid>> Publish(){var exams=await admin.GetFromJsonAsync<JsonElement>("/api/admin/exams");var ids=exams.EnumerateArray().Select(x=>x.GetProperty("id").GetGuid()).ToList();foreach(var id in ids)await Read(await admin.PostAsJsonAsync($"/api/admin/exams/{id}/publish",new{confirmTeacherReview=true}));await Read(await admin.PutAsJsonAsync("/api/admin/settings",new{paymentInstructions="TEST ONLY - do not send money",contactEmail="test@example.test",acceptPayments=true}));return ids;}
 private async Task<Guid> Payment(HttpClient student){var r=await Read(await student.PostAsJsonAsync("/api/payments",new{reference=Guid.NewGuid().ToString(),idempotencyKey=Guid.NewGuid().ToString()}));return r.GetProperty("id").GetGuid();}
 private async Task<(HttpClient Student,List<Guid> Exams)> Enroll(){var ids=await Publish();var student=await Student();var p=await Payment(student);await Read(await admin.PostAsJsonAsync($"/api/admin/payments/{p}/approve",new{bankVerified=true,note="Synthetic test bank record"}));return(student,ids);}
 private static async Task<Guid> Start(HttpClient s,Guid exam)=>(await Read(await s.PostAsync($"/api/exams/{exam}/attempts",null))).GetProperty("id").GetGuid();
 [Fact]public async Task HealthAndPilotTerms(){Assert.Equal(HttpStatusCode.OK,(await client.GetAsync("/api/health")).StatusCode);var p=await client.GetFromJsonAsync<PilotPackage>("/api/public/package");Assert.NotNull(p);Assert.Equal(500m,p.Price);Assert.False(p.PurchasesEnabled);Assert.Equal(5,p.ExamCount);Assert.Equal(40,p.QuestionsPerExam);Assert.Equal(2.5m,p.MarksPerQuestion);Assert.Equal(60,p.DurationMinutes);}
 [Fact]public async Task RegistrationLoginRolesAndIsolation(){using var s=await Student();Assert.Equal(HttpStatusCode.OK,(await s.GetAsync("/api/auth/me")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await s.GetAsync("/api/admin/payments")).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync("/api/dashboard")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await s.GetAsync("/api/dashboard?studentId=someone-else")).StatusCode);var bad=await client.PostAsJsonAsync("/api/auth/register",new{email="bad@example.test",password=Password,displayName="Bad",role="Administrator",guardianConsent=true});Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);}
 [Fact]public async Task GuardianConsentAndPasswordValidation(){var r=await client.PostAsJsonAsync("/api/auth/register",new{email="child@example.test",password=Password,displayName="Child",role="Student",guardianConsent=false});Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);r=await client.PostAsJsonAsync("/api/auth/register",new{email="weak@example.test",password="short",displayName="Child",role="Student",guardianConsent=true});Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);}
 [Fact]public async Task WrongPasswordIsRejected(){var r=await client.PostAsJsonAsync("/api/auth/login",new{email="admin@example.test",password="wrong"});Assert.Equal(HttpStatusCode.Unauthorized,r.StatusCode);}
 [Fact]public async Task CorsAllowsOnlyConfiguredOrigin(){using var allowed=new HttpRequestMessage(HttpMethod.Get,"/api/health");allowed.Headers.Add("Origin","http://localhost:5173");using var a=await client.SendAsync(allowed);Assert.Equal("http://localhost:5173",Assert.Single(a.Headers.GetValues("Access-Control-Allow-Origin")));using var denied=new HttpRequestMessage(HttpMethod.Get,"/api/health");denied.Headers.Add("Origin","https://evil.invalid");using var d=await client.SendAsync(denied);Assert.False(d.Headers.Contains("Access-Control-Allow-Origin"));}
 [Fact]public async Task NoAccessWithoutApprovedPayment(){var ids=await Publish();using var s=await Student();Assert.Equal(HttpStatusCode.Forbidden,(await s.PostAsync($"/api/exams/{ids[0]}/attempts",null)).StatusCode);var p=await Payment(s);Assert.Equal(HttpStatusCode.Forbidden,(await s.PostAsync($"/api/exams/{ids[0]}/attempts",null)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await s.PostAsJsonAsync($"/api/admin/payments/{p}/approve",new{bankVerified=true,note="not authorized"})).StatusCode);await Read(await admin.PostAsJsonAsync($"/api/admin/payments/{p}/reject",new{bankVerified=false,note="No bank record"}));Assert.Equal(HttpStatusCode.Forbidden,(await s.PostAsync($"/api/exams/{ids[0]}/attempts",null)).StatusCode);}
 [Fact]public async Task ApprovalRequiresBankVerificationAndIsIdempotent(){var ids=await Publish();using var s=await Student();var p=await Payment(s);Assert.Equal(HttpStatusCode.BadRequest,(await admin.PostAsJsonAsync($"/api/admin/payments/{p}/approve",new{bankVerified=false,note="Only a screenshot"})).StatusCode);await Read(await admin.PostAsJsonAsync($"/api/admin/payments/{p}/approve",new{bankVerified=true,note="Verified"}));await Read(await admin.PostAsJsonAsync($"/api/admin/payments/{p}/approve",new{bankVerified=true,note="Verified"}));var subs=await s.GetFromJsonAsync<JsonElement>("/api/subscriptions/me");Assert.Equal(1,subs.GetArrayLength());Assert.Equal(5,subs[0].GetProperty("remaining").GetInt32());}
 [Fact]public async Task PaymentDraftRequiresOwnedReferenceBeforeApproval(){await Publish();using var s=await Student();using var other=await Student();var draft=await Read(await s.PostAsJsonAsync("/api/payments",new{reference=(string?)null,idempotencyKey=Guid.NewGuid().ToString()}));var id=draft.GetProperty("id").GetGuid();Assert.Equal("AwaitingReference",draft.GetProperty("status").GetString());Assert.Equal(HttpStatusCode.Conflict,(await admin.PostAsJsonAsync($"/api/admin/payments/{id}/approve",new{bankVerified=true,note="No reference"})).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await other.PutAsJsonAsync($"/api/payments/{id}/reference",new{reference="OTHER-REFERENCE"})).StatusCode);await Read(await s.PutAsJsonAsync($"/api/payments/{id}/reference",new{reference="OWNED-REFERENCE"}));await Read(await admin.PostAsJsonAsync($"/api/admin/payments/{id}/approve",new{bankVerified=true,note="Verified"}));}
 [Fact]public async Task DuplicateReferenceCannotActivateAnotherAccount(){await Publish();using var s=await Student();using var other=await Student();var reference=Guid.NewGuid().ToString();var key=Guid.NewGuid().ToString();var request=new{reference,idempotencyKey=key};var p=await Read(await s.PostAsJsonAsync("/api/payments",request));var repeat=await Read(await s.PostAsJsonAsync("/api/payments",request));Assert.Equal(p.GetProperty("id").GetGuid(),repeat.GetProperty("id").GetGuid());Assert.Equal(HttpStatusCode.Conflict,(await other.PostAsJsonAsync("/api/payments",new{reference,idempotencyKey=Guid.NewGuid().ToString()})).StatusCode);}
 [Fact]public async Task AnswersPersistAndCorrectAnswersStayHidden(){var (s,ids)=await Enroll();using(s){var id=await Start(s,ids[0]);var q=await s.GetFromJsonAsync<JsonElement>($"/api/attempts/{id}/questions");var raw=q.GetRawText();Assert.DoesNotContain("isCorrect",raw);Assert.DoesNotContain("explanation",raw);var first=q.GetProperty("questions")[0];var answer=new{questionId=first.GetProperty("id").GetGuid(),optionId=first.GetProperty("options")[0].GetProperty("id").GetGuid()};await Read(await s.PutAsJsonAsync($"/api/attempts/{id}/answers",answer));var restored=await s.GetFromJsonAsync<JsonElement>($"/api/attempts/{id}/questions");Assert.Equal(1,restored.GetProperty("answers").GetArrayLength());Assert.Equal(HttpStatusCode.Conflict,(await s.GetAsync($"/api/attempts/{id}/result")).StatusCode);using var other=await Student();Assert.Equal(HttpStatusCode.NotFound,(await other.GetAsync($"/api/attempts/{id}/questions")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await other.PostAsync($"/api/attempts/{id}/submit",null)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await other.GetAsync($"/api/attempts/{id}/result")).StatusCode);}}
 [Fact]public async Task InvalidOptionCannotBeSaved(){var (s,ids)=await Enroll();using(s){var id=await Start(s,ids[0]);Assert.Equal(HttpStatusCode.BadRequest,(await s.PutAsJsonAsync($"/api/attempts/{id}/answers",new{questionId=Guid.NewGuid(),optionId=Guid.NewGuid()})).StatusCode);}}
 [Fact]public async Task ConcurrentStartUsesOneEntitlement(){var (s,ids)=await Enroll();using(s){var results=await Task.WhenAll(Start(s,ids[0]),Start(s,ids[0]));Assert.Equal(results[0],results[1]);var subs=await s.GetFromJsonAsync<JsonElement>("/api/subscriptions/me");Assert.Equal(4,subs[0].GetProperty("remaining").GetInt32());await Read(await s.PostAsync($"/api/attempts/{results[0]}/submit",null));Assert.Equal(HttpStatusCode.Forbidden,(await s.PostAsync($"/api/exams/{ids[0]}/attempts",null)).StatusCode);}}
 [Theory][InlineData(23,0)][InlineData(24,1)][InlineData(31,1)][InlineData(32,2)]public async Task FractionalMarksRespectActualRewardThresholds(int correct,int badges){var (s,ids)=await Enroll();using(s){var id=await Start(s,ids[0]);using(var scope=host.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<AppDb>();var answers=await db.Questions.Where(q=>q.ExamId==ids[0]).OrderBy(q=>q.DisplayOrder).Take(correct).Select(q=>new{questionId=q.Id,optionId=q.Options.Single(o=>o.IsCorrect).Id}).ToListAsync();foreach(var answer in answers)await Read(await s.PutAsJsonAsync($"/api/attempts/{id}/answers",answer));}var result=await Read(await s.PostAsJsonAsync($"/api/attempts/{id}/submit",new{score=100,passed=true}));Assert.Equal(correct*2.5m,result.GetProperty("score").GetDecimal());var rewards=await s.GetFromJsonAsync<JsonElement>("/api/rewards/me");Assert.Equal(badges,rewards.GetArrayLength());}}
 [Fact]public async Task FullScoresDuplicateSubmissionRewardsAndChampion(){var (s,ids)=await Enroll();using(s){foreach(var exam in ids){var id=await Start(s,exam);using(var scope=host.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<AppDb>();var answers=await db.Questions.Where(q=>q.ExamId==exam).Select(q=>new{questionId=q.Id,optionId=q.Options.Single(o=>o.IsCorrect).Id}).ToListAsync();foreach(var answer in answers)await Read(await s.PutAsJsonAsync($"/api/attempts/{id}/answers",answer));}var submissions=await Task.WhenAll(s.PostAsync($"/api/attempts/{id}/submit",null),s.PostAsync($"/api/attempts/{id}/submit",null));foreach(var response in submissions){var result=await Read(response);Assert.Equal(100,result.GetProperty("score").GetDecimal());}var resultPage=await s.GetFromJsonAsync<JsonElement>($"/api/attempts/{id}/result");Assert.Contains("explanation",resultPage.GetRawText());}var rewards=await s.GetFromJsonAsync<JsonElement>("/api/rewards/me");Assert.Equal(11,rewards.GetArrayLength());Assert.Single(rewards.EnumerateArray(),x=>x.GetProperty("code").GetString()=="SCHOLARSHIP_CHAMPION");var subs=await s.GetFromJsonAsync<JsonElement>("/api/subscriptions/me");Assert.Equal(0,subs[0].GetProperty("remaining").GetInt32());}}
 [Fact]public async Task ExpiredAttemptRejectsLateAnswersAndFinalizes(){var (s,ids)=await Enroll();using(s){var id=await Start(s,ids[0]);using(var scope=host.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<AppDb>();var a=await db.Attempts.FindAsync(id);a!.ExpiresAt=DateTime.UtcNow.AddSeconds(-1);await db.SaveChangesAsync();}var saved=await Read(await s.PutAsJsonAsync($"/api/attempts/{id}/answers",new{questionId=Guid.NewGuid(),optionId=Guid.NewGuid()}));Assert.False(saved.GetProperty("saved").GetBoolean());var result=await s.GetFromJsonAsync<JsonElement>($"/api/attempts/{id}/result");Assert.Equal("Expired",result.GetProperty("status").GetString());Assert.Equal(0,result.GetProperty("score").GetDecimal());}}
 [Fact]public async Task ContentImportIsValidatedAtomicAndIdempotent(){var json=await File.ReadAllTextAsync(Path.Combine(AppContext.BaseDirectory,"data","model-exams.ta.json"));var dto=JsonSerializer.Deserialize<ImportDto>(json,new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;var result=await Read(await admin.PostAsJsonAsync("/api/admin/import",dto));Assert.Equal(5,result.GetProperty("unchanged").GetInt32());var malformed=dto with{Exams=dto.Exams.Select((e,i)=>i==0?e with{Questions=e.Questions.Take(39).ToList()}:e).ToList()};Assert.Equal(HttpStatusCode.BadRequest,(await admin.PostAsJsonAsync("/api/admin/import",malformed)).StatusCode);var exams=await admin.GetFromJsonAsync<JsonElement>("/api/admin/exams");Assert.All(exams.EnumerateArray(),e=>Assert.Equal(40,e.GetProperty("questionCount").GetInt32()));}
 [Fact]public async Task PublicationNeedsTeacherConfirmation(){var exams=await admin.GetFromJsonAsync<JsonElement>("/api/admin/exams");Assert.Equal(HttpStatusCode.BadRequest,(await admin.PostAsJsonAsync($"/api/admin/exams/{exams[0].GetProperty("id").GetGuid()}/publish",new{confirmTeacherReview=false})).StatusCode);}
 [Fact]public async Task PaidContentCannotBeEdited(){var (s,ids)=await Enroll();using(s){var r=await admin.PutAsJsonAsync($"/api/admin/exams/{ids[0]}",new{title="Changed",description="Changed",durationMinutes=60,passPercentage=60});Assert.Equal(HttpStatusCode.Conflict,r.StatusCode);}}
 [Fact]public async Task ParentCanOnlyViewCreatedChildren(){var email=Guid.NewGuid()+"@example.test";await Read(await client.PostAsJsonAsync("/api/auth/register",new{email,password=Password,displayName="Parent",role="Parent",guardianConsent=true}));using var p=await Login(email);var child=await Read(await p.PostAsJsonAsync("/api/parent/children",new{displayName="Child",password=Password,guardianConsent=true}));var childId=child.GetProperty("id").GetString();Assert.Equal(HttpStatusCode.OK,(await p.GetAsync("/api/dashboard?studentId="+childId)).StatusCode);using var stranger=await Student();Assert.Equal(HttpStatusCode.NotFound,(await stranger.GetAsync("/api/dashboard?studentId="+childId)).StatusCode);using var childClient=await Login(child.GetProperty("email").GetString()!);Assert.Equal(HttpStatusCode.OK,(await childClient.GetAsync("/api/dashboard")).StatusCode);}
}
public class ScoringTests {
 [Theory][InlineData(59,0)][InlineData(60,1)][InlineData(79,1)][InlineData(80,2)][InlineData(100,2)]public void ExactRewardBoundaries(int percentage,int count)=>Assert.Equal(count,Scoring.Badges(percentage).Length);
 [Fact]public void RepeatedExamIsNotChampion(){var id=Guid.NewGuid();Assert.False(Scoring.Champion(Enumerable.Range(0,5).Select(_=>(id,60m))));}
 [Fact]public void FiveDistinctPassingExamsAreChampion()=>Assert.True(Scoring.Champion(Enumerable.Range(0,5).Select(_=>(Guid.NewGuid(),60m))));
 [Fact]public void OneFailingExamPreventsChampion()=>Assert.False(Scoring.Champion(Enumerable.Range(0,5).Select(i=>(Guid.NewGuid(),i==4?59m:80m))));
 [Fact]public void PercentageCalculation()=>Assert.Equal(60m,Scoring.Percentage(24*2.5m,100));
}
